          '_Previous review discussions for PR #' + pullRequestId + '._\n\n' +
          sections.join('\n')
        : null;

    const raw = rawThreads.length > 0
        ? { threads: rawThreads, census: inv ? inv.census : null }
        : null;

    return { markdown: markdown, rawThreads: raw };
