    if (!url) return null;
    if (/\/actions\/runs\/\d+/.test(url)) return null;
    var m = url.match(/\/runs\/(\d+)/);
    return m ? m[1] : null;
}

/** Extract the numeric workflow-run id from a details_url shaped /runs/{id}. */
