            var logs = unwrapLogResult(rawLogs);
            if (logs) return { logs: logs };
            return { reason: 'job log for ' + jobIdMatch[1] + ' came back empty' };
        } catch (e) {
            console.warn('Could not fetch logs for job', jobIdMatch[1], ':', e.message || e);
