            var checkRunLogs = _fetchJobLogs(scm, owner, repo, checkRunId);
            if (checkRunLogs) return { logs: checkRunLogs };
            return { reason: 'check-run ' + checkRunId + ' log came back empty (check run is not backed by a GitHub Actions job?)' };

